"""Floyd-Warshall all-pairs shortest path algorithm."""

import math


def floyd_warshall(graph: list[list[float]]) -> list[list[float]]:
    """Compute shortest paths between all pairs of vertices.

    Args:
        graph: Adjacency matrix where graph[i][j] is the edge weight
               from vertex i to j. Use math.inf for absent edges.
               Diagonal entries should be 0.

    Returns:
        dist: dist[i][j] is the shortest distance from i to j.
    """
    n = len(graph)
    dist = [row[:] for row in graph]

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist


def floyd_warshall_with_path(graph: list[list[float]]) -> tuple[list[list[float]], list[list[int | None]]]:
    """Like floyd_warshall, but also returns a successor matrix for path reconstruction."""
    n = len(graph)
    dist = [row[:] for row in graph]
    nxt: list[list[int | None]] = [[None] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i != j and graph[i][j] != math.inf:
                nxt[i][j] = j

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    nxt[i][j] = nxt[i][k]

    return dist, nxt


def reconstruct_path(nxt: list[list[int | None]], u: int, v: int) -> list[int] | None:
    """Reconstruct the shortest path from u to v using the successor matrix."""
    if nxt[u][v] is None:
        return None
    path = [u]
    while u != v:
        u = nxt[u][v]
        if u is None:
            return None
        path.append(u)
    return path


if __name__ == "__main__":
    inf = math.inf
    graph = [
        [0,   3,   inf, 5],
        [2,   0,   inf, 4],
        [inf, 1,   0,   inf],
        [inf, inf, 2,   0],
    ]

    dist = floyd_warshall(graph)
    print("Shortest distance matrix:")
    for row in dist:
        print([x if x != inf else "INF" for x in row])

    dist2, nxt = floyd_warshall_with_path(graph)
    print("\nPaths:")
    for i in range(len(graph)):
        for j in range(len(graph)):
            if i != j:
                path = reconstruct_path(nxt, i, j)
                print(f"  {i} -> {j}: path={path}, dist={dist2[i][j]}")
